public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Build a set of substrings for each string
    List<Set<String>> substringSets = new ArrayList<>(strings.size());
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            substringSets.add(Collections.emptySet());
            continue;
        }
        minLen = Math.min(minLen, s.length());
        Set<String> set = new HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                set.add(s.substring(i, j));
            }
        }
        substringSets.add(set);
    }
    if (minLen == Integer.MAX_VALUE) { // all were null
        return 0;
    }
    // Use the first string as source of candidate substrings
    String first = strings.get(0);
    if (first == null) {
        return 0;
    }
    for (int l = minLen; l >= 1; l--) {
        Set<String> seen = new HashSet<>();
        for (int i = 0; i <= first.length() - l; i++) {
            String candidate = first.substring(i, i + l);
            if (!seen.add(candidate)) {
                continue; // already processed this substring
            }
            String rev = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (Set<String> set : substringSets) {
                if (!set.contains(candidate) && !set.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return l;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{i, j});
                visited[i][j] = true;

                while (!stack.isEmpty()) {
                    int[] cur = stack.pop();
                    int r = cur[0];
                    int c = cur[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = r + dRow[k];
                        int nc = c + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // Maximum number of regions produced by N triangles in general position
    // Formula: R(N) = 3 * N * (N - 1) + 2
