public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 != 0) {
            continue;
        }
        int half = num / 2;
        Integer halfCount = freq.get(half);
        if (halfCount != null) {
            if (half != num || halfCount > 1) {
                count++;
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) {
        throw new IllegalArgumentException("Size n must be positive");
    }
    if (start == null || end == null) {
        throw new IllegalArgumentException("Start and end coordinates must not be null");
    }
    int dim = start.length;
    if (dim != end.length) {
        throw new IllegalArgumentException("Start and end must have the same dimension");
    }
    if (dim == 0) {
        throw new IllegalArgumentException("Coordinate dimension must be non-zero");
    }
    // Coordinates must be within [0, n-1] for each dimension
    for (int i = 0; i < dim; i++) {
        if (start[i] < 0 || start[i] >= n || end[i] < 0 || end[i] >= n) {
            throw new IllegalArgumentException("Coordinate values must be within the grid bounds");
        }
    }
    // Helper to convert coordinate array to string key
    java.util.function.Function<int[], String> keyFunc = arr -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < arr.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(arr[i]);
        }
        return sb.toString();
    };
    String startKey = keyFunc.apply(start);
    String endKey = keyFunc.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p == null || p.length != 2 * dim) {
            throw new IllegalArgumentException("Each path must contain " + (2 * dim) + " integers");
        }
        int[] a = new int[dim];
        int[] b = new int[dim];
        for (int i = 0; i < dim; i++) {
            a[i] = p[i];
            b[i] = p[i + dim];
            if (a[i] < 0 || a[i] >= n || b[i] < 0 || b[i] >= n) {
                throw new IllegalArgumentException("Path coordinates out of bounds");
            }
        }
        String aKey = keyFunc.apply(a);
        String bKey = keyFunc.apply(b);
        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }
    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neigh = adj.getOrDefault(cur, java.util.Collections.emptyList());
        for (String nxt : neigh) {
            if (visited.contains(nxt)) {
                continue;
            }
            if (nxt.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(nxt);
            queue.offer(nxt);
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    try {
        // Split the input string into month, day, and year components
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid date format";
        }

        int month = Integer.parseInt(parts[0]);
        int day   = Integer.parseInt(parts[1]);
        int year  = Integer.parseInt(parts[2]);

        // Create a LocalDate instance for the given date
        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        // Format the date as "Month day, year"
        java.time.format.DateTimeFormatter dateFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy");
        String formattedDate = localDate.format(dateFormatter);

        // Determine the weekday name
        java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();
        String weekday = dayOfWeek.toString().charAt(0) +
                         dayOfWeek.toString().substring(1).toLowerCase();

        return formattedDate + " is a " + weekday;
    } catch (Exception e) {
        // Handle parsing errors, invalid dates, etc.
        return "Invalid date";
    }
}

public int[] twoSum(int[] nums, int target) {
    // Validate input
    if (nums == null || nums.length < 2) {
        return new int[]{-1, -1};
    }

    // Brute-force search for two indices whose values sum to target
    for (int i = 0; i < nums.length; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[i] + nums[j] == target) {
                return new int[]{i, j};
            }
        }
    }

    // As per problem statement, there is exactly one solution,
    // but return error indices if none found to be robust.
    return new int[]{-1, -1};
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which part is normally sorted
        if (nums[left] <= nums[mid]) {
            // Left to mid is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            // Mid to right is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int removeCount = (int) Math.floor(n * 0.05);
    if (removeCount * 2 >= n) {
        return 0.0;
    }
    int[] copy = java.util.Arrays.copyOf(arr, n);
    java.util.Arrays.sort(copy);
    double sum = 0.0;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += copy[i];
    }
    int remaining = n - 2 * removeCount;
    return remaining > 0 ? sum / remaining : 0.0;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        return false;
    }
    if (k <= 0) {
        // Division by non-positive numbers is not defined in this context
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        // Cannot form pairs if the array size is odd
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    // Remainder 0 must appear an even number of times
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, the remainder k/2 must also appear an even number of times
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For all other remainders, freq[r] must equal freq[k - r]
    int limit = k / 2;
    for (int r = 1; r <= limit; r++) {
        if (r == k - r) {
            // This case is handled when k is even and r == k/2
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        return 0;
    }
    if (edges == null || hasApple == null || hasApple.length < n) {
        throw new IllegalArgumentException("Invalid input");
    }
    java.util.List<java.util.List<Integer>> graph = new java.util.ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        graph.add(new java.util.ArrayList<>());
    }
    for (int[] e : edges) {
        if (e == null || e.length < 2) {
            continue;
        }
        int u = e[0];
        int v = e[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, java.util.List<java.util.List<Integer>> graph, boolean[] hasApple) {
    int total = 0;
    for (int child : graph.get(node)) {
        if (child == parent) {
            continue;
        }
        int childCost = dfs(child, node, graph, hasApple);
        if (childCost > 0 || hasApple[child]) {
            total += childCost + 2;
        }
    }
    return total;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }

    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);

    try {
        for (int num : nums) {
            for (int size = n - 1; size >= 0; size--) {
                if (dp[size].isEmpty()) continue;
                for (int sum : dp[size]) {
                    dp[size + 1].add(sum + num);
                }
            }
        }

        for (int k = 1; k <= n / 2; k++) {
            long product = (long) totalSum * k;
            if (product % n == 0) {
                int target = (int) (product / n);
                if (dp[k].contains(target)) {
                    return true;
                }
            }
        }
    } catch (Exception e) {
        // In case of any runtime issue, return false
        return false;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int fromPrev = dp[i - 1] + cost[i - 1];
        int fromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromPrev, fromPrevPrev);
    }
    return dp[n];
}

public int uniqueMorseRepresentations(String[] words) {
