    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    try {
        if (s == null || k < 0) {
            return false;
        }
        int n = s.length();
        if (k == 0) {
            return true;
        }
        if (n < k) {
            return false;
        }
        // Limit k to a reasonable size to avoid excessive memory usage
        if (k > 20) {
            return false;
        }
        int totalCodes = 1 << k;
        boolean[] seen = new boolean[totalCodes];
        int code = 0;
        // Build the first code of length k
        for (int i = 0; i < k; i++) {
            code = (code << 1) | (s.charAt(i) - '0');
        }
        seen[code] = true;
        int mask = totalCodes - 1;
        // Slide the window across the string
        for (int i = k; i < n; i++) {
            code = ((code << 1) & mask) | (s.charAt(i) - '0');
            seen[code] = true;
        }
        // Check if all codes have been seen
        for (boolean flag : seen) {
            if (!flag) {
                return false;
            }
        }
        return true;
    } catch (Exception e) {
        return false;
    }
}

