public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int need = 0; // number of '(' needed to balance upcoming ')'
    int ans = 0;  // total insertions required
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            need++;
        } else if (c == ')') {
            need--;
            if (need < 0) {
                ans++;      // insert a '(' before this ')'
                need = 0;
            }
        } else {
            // Invalid character, skip or throw exception as needed
            // For robustness, treat it as no-op
        }
    }
    // Remaining unmatched '(' require ')' insertions
    ans += need;
    return ans;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    long target = n;            // The value each element should become
    long totalAbsDiff = 0L;     // Sum of absolute differences from the target

    for (int i = 0; i < n; i++) {
        long current = 2L * i + 1L;          // arr[i] = 2*i + 1
        totalAbsDiff += Math.abs(current - target);
    }

    // Each operation reduces the total deviation by 2 (1 from a surplus, 1 to a deficit)
    return (int) (totalAbsDiff / 2);
}

