public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Generate Fibonacci numbers up to k (including duplicates of 1)
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy selection: pick the largest Fibonacci number <= remaining
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> low = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> high = new java.util.ArrayList<>();
    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            low.add(i);
            int other = n / i;
            if (other != i) {
                high.add(other);
            }
        }
    }
    java.util.Collections.sort(high);
    int total = low.size() + high.size();
    if (k > total) {
        return -1;
    }
    if (k <= low.size()) {
        return low.get(k - 1);
    } else {
        return high.get(k - low.size() - 1);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Math.abs(last - c) == 32) { // one is lowercase, other is uppercase of same letter
                stack.setLength(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    java.util.HashSet<String> used = new java.util.HashSet<>();
    return backtrack(s, 0, used);
}

private int backtrack(String s, int index, java.util.HashSet<String> used) {
    int n = s.length();
    if (index == n) {
        return 0;
    }
    int maxSplits = 0;
    for (int end = index + 1; end <= n; end++) {
        String sub = s.substring(index, end);
        if (used.contains(sub)) {
            continue; // duplicate substring, cannot use
        }
        used.add(sub);
        int splits = 1 + backtrack(s, end, used);
        if (splits > maxSplits) {
            maxSplits = splits;
        }
        used.remove(sub);
    }
    return maxSplits;
}

public int minOperations(String[] logs) {
    // Handle null input
    if (logs == null) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if ("../".equals(log)) {
            if (depth > 0) {
                depth--;
            }
        } else if ("./".equals(log)) {
            // stay in current folder, no change
            continue;
        } else {
            // any other log represents entering a subfolder
            depth++;
        }
    }
    // The minimum steps to return to the main folder is the current depth
    return depth;
}

public String getSmallestString(int n, int k) {
    // Validate input
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive.");
    }
    int minSum = n * 1;          // all 'a'
    int maxSum = n * 26;         // all 'z'
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException(
            "k is out of valid range [" + minSum + ", " + maxSum + "].");
    }

    char[] chars = new char[n];
    java.util.Arrays.fill(chars, 'a');      // start with "aaaa..."
    int remaining = k - n;                  // value we need to add beyond all 'a's

    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);  // each position can increase up to 25 (from 'a' to 'z')
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }

    // At this point remaining should be 0
    if (remaining != 0) {
        // This should not happen because of earlier range check, but guard anyway
        throw new IllegalStateException("Unable to construct valid string; remaining=" + remaining);
    }

    return new String(chars);
}

