public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int columnSum = 0;
        for (int num : nums) {
            columnSum += (num >> i) & 1;
        }
        result |= (columnSum % 3) << i;
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high || high < 0) {
        return result;
    }
    // Helper function using recursion
    java.util.function.BiConsumer<Long, Integer> dfs = new java.util.function.BiConsumer<Long, Integer>() {
        @Override
        public void accept(Long num, Integer lastDigit) {
            if (num > high) {
                return;
            }
            if (num >= low && num <= high) {
                result.add(num.intValue());
            }
            if (num == 0) {
                return; // avoid leading zeros
            }
            if (lastDigit > 0) {
                long child = num * 10 + (lastDigit - 1);
                if (child <= high) {
                    this.accept(child, lastDigit - 1);
                }
            }
            if (lastDigit < 9) {
                long child = num * 10 + (lastDigit + 1);
                if (child <= high) {
                    this.accept(child, lastDigit + 1);
                }
            }
        }
    };

    for (int i = 0; i <= 9; i++) {
        dfs.accept((long) i, i);
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long N = n;
    while (N / factor > 0) {
        long higher = N / (factor * 10);
        long current = (N / factor) % 10;
        long lower = N % factor;
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // A number is a power of 2 if only one bit is set in its binary representation.
    // n & (n - 1) will clear the lowest set bit. If the result is 0, then n was a power of two.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    try {
        if (mat == null || mat.length == 0) {
            return 0;
        }
        int m = mat.length;
        int n = mat[0].length;
        // Validate that all rows have the same length
        for (int[] row : mat) {
            if (row == null || row.length != n) {
                return 0;
            }
        }

        int[][] horiz = new int[m][n];
        int[][] vert = new int[m][n];
        int[][] diag = new int[m][n];
        int[][] anti = new int[m][n];
        int maxLen = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                    vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                    diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                    anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;

                    int currentMax = Math.max(
                            Math.max(horiz[i][j], vert[i][j]),
                            Math.max(diag[i][j], anti[i][j]));
                    if (currentMax > maxLen) {
                        maxLen = currentMax;
                    }
                }
            }
        }
        return maxLen;
    } catch (Exception e) {
        // In case of any runtime issue, return 0 as a safe fallback
        return 0;
    }
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long abs = Math.abs((long) n);
    String numStr = Long.toString(abs);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i > 0) {
            sb.append('.');
            count = 0;
        }
    }
    String result = sb.reverse().toString();
    return negative ? "-" + result : result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    long maxArea = 0;
    int i = 0;
    while (i < n) {
        if (top == -1 || heights[i] >= heights[stack[top]]) {
            stack[++top] = i++;
        } else {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
    }
    while (top != -1) {
        int height = heights[stack[top--]];
        int width = (top == -1) ? n : n - stack[top] - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    int totalDiagonals = m + n - 1;
    for (int d = 0; d < totalDiagonals; d++) {
        int rowStart = Math.max(0, d - (n - 1));
        int rowEnd = Math.min(m - 1, d);
        if (d % 2 == 0) { // even diagonal: traverse from bottom to top
            for (int row = rowEnd; row >= rowStart; row--) {
                int col = d - row;
                result[idx++] = mat[row][col];
            }
        } else { // odd diagonal: traverse from top to bottom
            for (int row = rowStart; row <= rowEnd; row++) {
                int col = d - row;
                result[idx++] = mat[row][col];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    // Convert the integer to an array of its digits
    String s = Integer.toString(n);
    int len = s.length();
    char[] digits = s.toCharArray();

    // Find the largest index i such that digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such index exists, the digits are in non‑increasing order
    if (i < 0) {
        return -1;
    }

    // Find the largest index j > i such that digits[j] > digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert the digit array back to a number
    long result = 0;
    for (char d : digits) {
        result = result * 10 + (d - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // overflow case, treat as impossible
        }
    }

    return (int) result;
}

public static boolean isBoomerang(int[][] points) {
    try {
        if (points == null || points.length != 3) {
            return false;
        }
        // Ensure each point has exactly two coordinates
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }
        // Check for duplicate points
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                    return false;
                }
            }
        }
        // Calculate area of triangle formed by the three points
        int x1 = points[0][0], y1 = points[0][1];
        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];
        int area2 = (x1 - x2) * (y3 - y2) - (y1 - y2) * (x3 - x2);
        // If area is zero, points are collinear
        return area2 != 0;
    } catch (Exception e) {
        // Any unexpected error results in false
        return false;
    }
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxRun = 1;
    int currentRun = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentRun++;
        } else {
            if (currentRun > maxRun) {
                maxRun = currentRun;
            }
            currentRun = 1;
        }
    }
    if (currentRun > maxRun) {
        maxRun = currentRun;
    }
    return maxRun;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        return 0;
    }
    java.util.Set<Integer> seen = new java.util.HashSet<>();
    java.util.Set<Integer> duplicates = new java.util.HashSet<>();
    for (int num : nums) {
        if (seen.contains(num)) {
            duplicates.add(num);
        } else {
            seen.add(num);
        }
    }
    int sum = 0;
    for (int num : seen) {
        if (!duplicates.contains(num)) {
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative: " + n);
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < s.length()) {
        if (Character.isWhitespace(s.charAt(i))) {
            result.append(s.charAt(i));
            i++;
        } else {
            int start = i;
            while (i < s.length() && !Character.isWhitespace(s.charAt(i))) {
                i++;
            }
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}
